<span class="line"><span style="color:#E1E4E8;">        EmailService emailService </span><span style="color:#F97583;">=</span><span style="color:#E1E4E8;"> context.</span><span style="color:#B392F0;">getBean</span><span style="color:#E1E4E8;">(</span><span style="color:#9ECBFF;">&quot;emailService&quot;</span><span style="color:#E1E4E8;">, EmailService.class);</span></span>
